# -*- coding: utf-8 -*-
"""Builds STEPS / ERRORS / DEMO data -> steps-data.json for the Phase 1 guide."""
import json

STEPS = []
_n = [0]


def step(section, title, screen, user_does, junior, you_supply, method, path,
         prereq, request, response, stored, triggers, states, done_when, source_files):
    _n[0] += 1
    STEPS.append({
        "id": f"s{_n[0]:02d}",
        "section": section,
        "num": _n[0],
        "title": title,
        "screen": screen,
        "user_does": user_does,
        "junior": junior,
        "you_supply": you_supply,
        "method": method,
        "path": path,
        "prereq": prereq,
        "request": request,
        "response": response,
        "stored": stored,
        "triggers": triggers,
        "states": states,
        "done_when": done_when,
        "source_files": source_files,
    })


