     "Nothing.",
     "POST", "/api/v1/auth/refresh/",
     ["Same as the Refresh step above — this IS that same call, just triggered by app startup instead of a timer/401."],
     {"headers": "X-CSRFToken: <csrfToken, fetched fresh first if needed>", "body": None, "query": None},
     {"status": 200, "body": {"access": "eyJhbGciOi..."}, "note": "Identical shape to the Refresh step."},
